function GetStackType(interpreter, index):
  max_index = *(ushort*)(interpreter + 0xe2)
  if index <= max_index:
    base_ptr = *(long*)(interpreter + 0xd8)
    element_offset = (max_index - index) * 8
    element_ptr = *(long*)(base_ptr + element_offset)
    element_type = *(byte*)(element_ptr + 0xa)
    if element_type == 0x15 or element_type == 0x0c:
      return 0x01
    else:
      return element_type
  else:
    return 0x17

